    text = read(rel)
    text = replace_once(text, "implementation_review_state: independent-review-no-pass-owner-binding-repair-open", "implementation_review_state: repaired-qualified-independent-review-pending", "close review state")
    text = replace_once(text, f"qualified_semantic_candidate: {OLD_CANDIDATE}", f"qualified_semantic_candidate: {candidate}", "close candidate")
