    marker = "f2_qualification: qualification/ssdp6/RESULTS-GPT-5.6-SOL-2026-09-12-PROTOCOL-6.3-F2.md"
    text = replace_once(text, marker, marker + f"\nf3_semantic_candidate: {candidate}\nf3_public_bootstrap: {bootstrap}\nf3_qualification: qualification/ssdp6/RESULTS-GPT-5.6-SOL-2026-09-12-PROTOCOL-6.3-F3.md", "close F3 metadata")
