def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("stage", choices=["reopen", "implement", "publish", "close"])
    parser.add_argument("--bootstrap")
    parser.add_argument("--candidate")
    args = parser.parse_args()
    if args.stage == "reopen":
        reopen_workplan()
    elif args.stage == "implement":
        implement_validator(); implement_project_memory(); implement_doctrine_and_template(); implement_tests(); invalidate_bootstrap()
    elif args.stage == "publish":
        if not args.bootstrap: raise SystemExit("--bootstrap required")
        publish_bootstrap(args.bootstrap)
    else:
        if not args.bootstrap or not args.candidate: raise SystemExit("--bootstrap and --candidate required")
        close_workplan(args.bootstrap, args.candidate)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
